            Add(translations,  ModTextKey.RowDifficultyTemplatesActions,  "Difficulty templates",  "Modèles de difficulté",  "Modelli difficoltà",  "Plantillas de dificultad",  "Шаблоны сложности",  "Modelos de dificuldade",  "Zorluk şablonları");
            Add(translations,  ModTextKey.RowDifficultyEnableAll,  "Enable all",  "Tout activer",  "Attiva tutto",  "Activar todo",  "Включить всё",  "Ativar tudo",  "Tümünü etkinleştir");
            Add(translations,  ModTextKey.RowDifficultyDisableAll,  "Disable all",  "Tout désactiver",  "Disattiva tutto",  "Desactivar todo",  "Выключить всё",  "Desativar tudo",  "Tümünü devre dışı bırak");
            Add(translations,  ModTextKey.RowDifficultySaveTemplate,  "Save template",  "Sauvegarder le modèle",  "Salva modello",  "Guardar plantilla",  "Сохранить шаблон",  "Salvar modelo",  "Şablonu kaydet");
            Add(translations,  ModTextKey.RowDifficultyLoadTemplate,  "Load template",  "Charger le modèle",  "Caricare modello",  "Cargar plantilla",  "Загрузить шаблон",  "Carregar modelo",  "Şablonu yükle");
            Add(translations,  ModTextKey.RowNoDifficultyTemplates,  "No templates saved",  "Aucun modèle sauvegardé",  "Nessun modello salvato",  "No hay plantillas guardadas",  "Нет сохраненных шаблонов",  "Nenhum modelo salvo",  "Kaydedilmiş şablon yok");
            Add(translations,  ModTextKey.RowEconomyPreset,  "Economy preset: < {0} >",  "Préréglage économie : < {0} >",  "Preset economia: < {0} >",  "Preajuste económico: < {0} >",  "Экономика: < {0} >",  "Predefinição econômica: < {0} >",  "Ekonomi ön ayarı: < {0} >");
            Add(translations,  ModTextKey.RowNpcWeeklyWages,  "NPC weekly wages: < {0} >",  "Salaires hebdo PNJ : < {0} >",  "Salari settimanali NPC: < {0} >",  "Sueldos semanales NPC: < {0} >",  "Недельная зарплата NPC: < {0} >",  "Salários semanais dos NPCs: < {0} >",  "NPC haftalık ücretleri: < {0} >");
            Add(translations,  ModTextKey.RowStartingBalance,  "Starting balance: {0}",  "Solde initial : {0}",  "Saldo iniziale: {0}",  "Saldo inicial: {0}",  "Стартовый баланс: {0}",  "Saldo inicial: {0}",  "Başlangıç bakiyesi: {0}");
            Add(translations,  ModTextKey.RowStartingGuides,  "Starting guides",  "Guides de démarrage",  "Guide introduttive",  "Guías de inicio",  "Стартовые руководства",  "Guias de início",  "Başlangıç rehberleri");
            Add(translations,  ModTextKey.RowActivate,  "Activate: {0}",  "Activer : {0}",  "Attiva: {0}",  "Activar: {0}",  "Активировать: {0}",  "Ativar: {0}",  "Etkinleştir: {0}");

            Add(translations,  ModTextKey.DetailSavingOptions,  "Create, load, delete, or save named games. Active: {0}.",  "Créer, charger, supprimer ou sauvegarder des parties nommées. Active : {0}.",  "Crea, carica, elimina o salva partite nominate. Attiva: {0}.",  "Crea, carga, elimina o guarda partidas con nombre. Activa: {0}.",  "Создавайте, загружайте, удаляйте и сохраняйте именованные игры. Активно: {0}.",  "Crie, carregue, exclua ou salve jogos nomeados. Ativo: {0}.",  "Adlandırılmış kayıtlar oluşturun, yükleyin, silin veya kaydedin. Etkin: {0}.");
            Add(translations,  ModTextKey.DetailDifficultyUnlocked,  "Review the full gameplay difficulty profile. Economy: {0} | NPC wages: {1} | routes: {2} | challenge rules on: {3}.",  "Consultez le profil complet de difficulté. Économie : {0} | salaires PNJ : {1} | routes : {2} | règles actives : {3}.",  "Controlla il profilo difficoltà completo. Economia: {0} | salari NPC: {1} | rotte: {2} | regole attive: {3}.",  "Revisa el perfil completo de dificultad. Economía: {0} | salarios NPC: {1} | rutas: {2} | reglas activas: {3}.",  "Просмотрите полный профиль сложности. Экономика: {0} | зарплаты NPC: {1} | маршруты: {2} | активные правила: {3}.",  "Revise o perfil completo de dificuldade. Economia: {0} | salários de NPCs: {1} | rotas: {2} | regras ativas: {3}.",  "Tam zorluk profilini inceleyin. Ekonomi: {0} | NPC ücretleri: {1} | rotalar: {2} | açık kurallar: {3}.");
            Add(translations,  ModTextKey.DetailDifficultyLocked,  "Locked by the active save. Economy: {0} | NPC wages: {1} | routes: {2} | challenge rules on: {3}. Create a new save to change these settings.",  "Verrouillé par la sauvegarde active. Économie : {0} | salaires PNJ : {1} | routes : {2} | règles actives : {3}. Créez une nouvelle sauvegarde pour modifier ces paramètres.",  "Bloccato dal salvataggio attivo. Economia: {0} | salari NPC: {1} | rotte: {2} | regole attive: {3}. Crea un nuovo salvataggio per cambiare queste impostazioni.",  "Bloqueado por la partida activa. Economía: {0} | salarios NPC: {1} | rutas: {2} | reglas activas: {3}. Crea una nueva partida para cambiar estos ajustes.",  "Заблокировано активным сохранением. Экономика: {0} | зарплаты NPC: {1} | маршруты: {2} | активные правила: {3}. Создайте новое сохранение, чтобы изменить параметры.",  "Bloqueado pelo save ativo. Economia: {0} | salários de NPCs: {1} | rotas: {2} | regras ativas: {3}. Crie um novo save para alterar essas configurações.",  "Etkin kayıt tarafından kilitlendi. Ekonomi: {0} | NPC ücretleri: {1} | rotalar: {2} | açık kurallar: {3}. Bu ayarları değiştirmek için yeni kayıt oluşturun.");
            Add(translations,  ModTextKey.DetailCreateNewSave,  "Creates {0}.state.xml in {1}",  "Crée {0}.state.xml dans {1}",  "Crea {0}.state.xml in {1}",  "Crea {0}.state.xml en {1}",  "Создаёт {0}.state.xml в {1}",  "Cria {0}.state.xml em {1}",  "{1} içinde {0}.state.xml oluşturur");
            Add(translations,  ModTextKey.DetailLoadSave,  "Choose from all created savegames.",  "Choisissez parmi toutes les sauvegardes créées.",  "Scegli tra tutti i salvataggi creati.",  "Elige entre todas las partidas creadas.",  "Выберите одно из созданных сохранений.",  "Escolha entre todos os saves criados.",  "Oluşturulan tüm kayıtlardan seçin.");
            Add(translations,  ModTextKey.DetailDeleteSave,  "Delete one of your created savegames.",  "Supprimez une de vos sauvegardes.",  "Elimina uno dei tuoi salvataggi.",  "Elimina una de tus partidas creadas.",  "Удалите одно из созданных сохранений.",  "Exclua um dos seus saves criados.",  "Oluşturduğunuz kayıtlardan birini silin.");
            Add(translations,  ModTextKey.DetailSaveGame,  "Writes current progress to {0}.state.xml.",  "Écrit la progression actuelle dans {0}.state.xml.",  "Scrive i progressi correnti in {0}.state.xml.",  "Escribe el progreso actual en {0}.state.xml.",  "Записывает текущий прогресс в {0}.state.xml.",  "Grava o progresso atual em {0}.state.xml.",  "Geçerli ilerlemeyi {0}.state.xml dosyasına yazar.");
            Add(translations,  ModTextKey.DetailNeedNamedSave,  "Create or load a named save first.",  "Créez ou chargez d'abord une sauvegarde nommée.",  "Crea o carica prima un salvataggio con nome.",  "Crea o carga primero una partida con nombre.",  "Сначала создайте или загрузите именованное сохранение.",  "Crie ou carregue um save nomeado primeiro.",  "Önce adlandırılmış bir kayıt oluşturun veya yükleyin.");
            Add(translations,  ModTextKey.DetailNoSavesFound,  "Create a save in {0} first.",  "Créez d'abord une sauvegarde dans {0}.",  "Crea prima un salvataggio in {0}.",  "Primero crea una partida en {0}.",  "Сначала создайте сохранение в {0}.",  "Crie primeiro um save em {0}.",  "Önce {0} içinde kayıt oluşturun.");
            Add(translations,  ModTextKey.DetailNewSaveStartingBalance,  "Choose the opening balance for the new save.",  "Choisissez le solde de départ pour la nouvelle sauvegarde.",  "Scegli il saldo iniziale per il nuovo salvataggio.",  "Elige el saldo inicial para la nueva partida.",  "Выберите стартовый баланс для нового сохранения.",  "Escolha o saldo inicial do novo save.",  "Yeni kayıt için başlangıç bakiyesini seçin.");
            Add(translations,  ModTextKey.DetailStartingGuides,  "Starting guides are step-by-step tasks that help new players learn this complex mod. Enabling them adds a checklist at the start of a new save.",  "Les guides de démarrage guident les nouveaux joueurs pas à pas dans ce mod complexe. L'activer ajoutera une checklist de départ à votre nouvelle sauvegarde.",  "Le guide introduttive sono serie di passaggi per aiutare i nuovi giocatori in questa mod complessa. Abilitandole aggiungerai una checklist all'inizio del tuo nuovo salvataggio.",  "Las guías de inicio son una serie de pasos para ayudar a los nuevos jugadores en este mod complejo. Activarlas añadirá una lista de tareas al inicio de tu nueva partida.",  "Стартовые руководства — это пошаговые инструкции для помощи новичкам в этом сложном моде. Включение добавит чек-лист задач в начале вашего нового сохранения.",  "Os guias de início são séries de passos para ajudar novos jogadores neste mod complexo. Ativá-los adicionará um checklist de tarefas no início do seu novo save.",  "Başlangıç rehberleri, yeni oyuncuların bu karmaşık modda ilerlemesine yardımcı olan adım dizileridir. Etkinleştirmek, yeni kaydınızın başında size bir kontrol listesi ekler.");
            
            Add(translations,  "startingGuides.panel.title",  "Starting Guide",  "Guide de démarrage",  "Guida introduttiva",  "Guia de inicio",  "Стартовое руководство",  "Guia de início",  "Başlangıç Rehberi");
            Add(translations,  "startingGuides.panel.complete",  "Starting guide complete.",  "Guide de démarrage terminé.",  "Guida introduttiva completata.",  "Guia de inicio completado.",  "Стартовое руководство завершено.",  "Guia de início concluído.",  "Başlangıç rehberi tamamlandı.");
            Add(translations,  "startingGuides.step.rentOffice.title",  "Rent office",  "Louer un bureau",  "Affitta ufficio",  "Alquilar oficina",  "Арендовать офис",  "Alugar escritório",  "Ofis kirala");
            Add(translations,  "startingGuides.step.rentOffice.instruction",  "Welcome to LSOL mod. Rent an office to unlock your company hub and garage. Offices usually use a white office icon. You can also open the F8 menu and browse Properties > Offices for more detail on available locations.",  "Bienvenue dans le mod LSOL. Louez un bureau pour débloquer le hub et le garage de votre entreprise. Les bureaux utilisent généralement une icône de bureau blanche. Vous pouvez également ouvrir le menu F8 et parcourir Propriétés > Bureaux pour plus de détails sur les emplacements disponibles.",  "Benvenuto nella mod LSOL. Affitta un ufficio per sbloccare l'hub aziendale e il garage. Gli uffici di solito usano un'icona dell'ufficio bianca. Puoi anche aprire il menu F8 e sfogliare Proprietà > Uffici per maggiori dettagli sulle posizioni disponibili.",  "Te damos la bienvenida al mod LSOL. Alquila una oficina para desbloquear el centro de tu empresa y el garaje. Las oficinas suelen usar un icono de oficina blanco. También puedes abrir el menú F8 y buscar Propiedades > Oficinas para obtener más detalles sobre las ubicaciones disponibles.",  "Добро пожаловать в мод LSOL. Арендуйте офис, чтобы разблокировать центр компании и гараж. Офисы обычно обозначаются белым значком офиса. Вы также можете открыть меню F8 и перейти в Проперти > Офисы для получения более подробной информации о доступных местах.",  "Bem-vindo ao mod LSOL. Alugue um escritório para desbloquear o hub e a garagem da sua empresa. Os escritórios geralmente usam um ícone de escritório branco. Você também pode abrir o menu F8 e navegar em Propriedades > Escritórios para mais detalhes sobre os locais disponíveis.",  "LSOL moduna hoş geldiniz. Şirket merkezinizi ve garajınızı açmak için bir ofis kiralayın. Ofisler genellikle beyaz bir ofis simgesi kullanır. Mevcut konumlar hakkında daha fazla ayrıntı için F8 menüsünü açıp Mülkler > Ofisler bölümüne de göz atabilirsiniz.");
            Add(translations,  "startingGuides.step.claimFreeTipper.title",  "Claim free Tipper",  "Réclamer le Tipper gratuit",  "Riscatta Tipper gratuito",  "Reclamar Tipper gratis",  "Получить бесплатный Tipper",  "Resgatar Tipper gratuito",  "Ücretsiz Tipper'ı al");
            Add(translations,  "startingGuides.step.claimFreeTipper.instruction",  "Go to the commercial dealership south of Los Santos and claim the free Tipper to start your first run. Hint: the Tipper is an aggregate cargo truck.",  "Rendez-vous chez le concessionnaire commercial au sud de Los Santos et réclamez le Tipper gratuit pour commencer votre premier trajet. Astuce : le Tipper est un camion de transport de granulats.",  "Vai alla concessionaria commerciale a sud di Los Santos e riscatta il Tipper gratuito per iniziare la tua prima corsa. Suggerimento: il Tipper è un camion per il trasporto di inerti.",  "Ve al concesionario comercial al sur de Los Santos y reclama el Tipper gratuito para comenzar tu primer trayecto. Consejo: el Tipper es un camión de carga de agregados.",  "Отправляйтесь в коммерческий автосалон к югу от Лос-Сантоса и получите бесплатный Tipper, чтобы начать свой первый рейс. Подсказка: Tipper — это грузовик для перевозки сыпучих грузов.",  "Vá até a concessionária comercial ao sul de Los Santos e resgate o Tipper gratuito para começar sua primeira corrida. Dica: o Tipper é um caminhão de carga de agregados.",  "İlk seferinize başlamak için Los Santos'un güneyindeki ticari araç galerisine gidin ve ücretsiz Tipper'ı alın. İpucu: Tipper, agrega yük kamyonudur.");
            Add(translations,  "startingGuides.step.retrieveTipperOffice.title",  "Retrieve Tipper at office",  "Récupérer le Tipper au bureau",  "Ritira Tipper in ufficio",  "Retirar Tipper en la oficina",  "Забрать Tipper у офиса",  "Retirar Tipper no escritório",  "Ofisten Tipper'ı çağır");
            Add(translations,  "startingGuides.step.retrieveTipperOffice.instruction",  "Spawn the Tipper from your office garage. Open the Office menu (press E when close), select 'Garage', select 'Tipper (4 Wheels)', then 'Retrieve'.",  "Faites apparaître le Tipper depuis le garage de votre bureau. Ouvrez le menu du bureau (appuyez sur E à proximité), sélectionnez 'Garage', sélectionnez 'Tipper (4 roues)', puis 'Récupérer'.",  "Fai spawnare il Tipper dal garage del tuo ufficio. Apri il menu dell'ufficio (premi E quando sei vicino), seleziona 'Garage', seleziona 'Tipper (4 ruote)', quindi 'Ritira'.",  "Aparece el Tipper desde el garaje de tu oficina. Abre el menú de la oficina (presiona E cuando estés cerca), selecciona 'Garaje', selecciona 'Tipper (4 ruedas)' y luego 'Retirar'.",  "Вызовите Tipper из гаража вашего офиса. Откройте меню офиса (нажмите E, находясь рядом), выберите 'Гараж', выберите 'Tipper (4 колеса)', затем 'Забрать'.",  "Gere o Tipper a partir da garagem do seu escritório. Abra o menu do escritório (pressione E quando estiver perto), selecione 'Garagem', selecione 'Tipper (4 Rodas)' e depois 'Retirar'.",  "Tipper'ı ofis garajınızdan çıkarın. Ofis menüsünü açın (yakındayken E'ye basın), 'Garaj'ı seçin, 'Tipper (4 Tekerlekli)' seçeneğini belirleyin ve ardından 'Çağır' deyin.");
            Add(translations,  "startingGuides.step.setGpsQuarry.title",  "Set GPS to Quarry",  "Définir le GPS vers la carrière",  "Imposta GPS su Cava",  "Fijar GPS hacia la cantera",  "Поставить GPS на карьер",  "Definir GPS para a Pedreira",  "GPS'i Taş Ocağına Ayarla");
            Add(translations,  "startingGuides.step.setGpsQuarry.instruction",  "Set a GPS waypoint to the quarry from the Company Hub. Press F8, select 'Industries', open 'Quarry', then select 'Add GPS Route'.",  "Définissez un point GPS vers la carrière depuis le hub de l'entreprise. Appuyez sur F8, sélectionnez 'Industries', ouvrez 'Carrière', puis sélectionnez 'Ajouter un itinéraire GPS'.",  "Imposta un waypoint GPS per la cava dall'hub aziendale. Premi F8, seleziona 'Industrie', apri 'Cava', quindi seleziona 'Aggiungi percorso GPS'.",  "Fija un punto GPS hacia la cantera desde el centro de la empresa. Presiona F8, selecciona 'Industrias', abre 'Cantera' и luego selecciona 'Añadir ruta GPS'.",  "Установите GPS-точку на карьер из центра компании. Нажмите F8, выберите 'Индустрии', откройте 'Карьер', затем выберите 'Добавить GPS-маршрут'.",  "Defina um ponto de referência GPS para a pedreira a partir do Hub da Empresa. Pressione F8, selecione 'Indústrias', abra 'Pedreira' e selecione 'Adicionar rota GPS'.",  "Şirket Merkezinden taş ocağına bir GPS rota noktası ayarlayın. F8'e basın, 'Sanayiler'i seçin, 'Taş Ocağı'nı açın, ardından 'GPS Rotası Ekle'yi seçin.");
            Add(translations,  "startingGuides.step.arriveQuarry.title",  "Arrive at Quarry",  "Arriver à la carrière",  "Arriva alla Cava",  "Llegar a la cantera",  "Прибыть на карьер",  "Chegar à Pedreira",  "Taş Ocağına Var");
            Add(translations,  "startingGuides.step.arriveQuarry.instruction",  "Drive to the quarry marker and line up for loading.",  "Conduisez jusqu'au marqueur de la carrière et alignez-vous pour le chargement.",  "Guida fino al marcatore della cava e allineati per il caricamento.",  "Conduce hasta el marcador de la cantera y alinéate para la carga.",  "Подъезжайте к маркеру карьера и встаньте в линию для загрузки.",  "Dirija até o marcador da pedreira e alinhe-se para o carregamento.",  "Taş ocağı işaretçisine sürün ve yükleme için sıraya girin.");
            Add(translations,  "startingGuides.step.loadCoal.title",  "Load Coal",  "Charger du charbon",  "Carica carbone",  "Cargar carbón",  "Загрузить уголь",  "Carregar carvão",  "Kömür Yükle");
            Add(translations,  "startingGuides.step.loadCoal.instruction",  "Approach the marker and load coal into the Tipper. Press E next to the industry, select 'Load Product', then choose 'Coal' if multiple products are available.",  "Approchez-vous du marqueur et chargez du charbon dans le Tipper. Appuyez sur E à côté de l'industrie, sélectionnez 'Charger le produit', puis choisissez 'Charbon' si plusieurs produits sont disponibles.",  "Avvicinati al marcatore e carica il carbone nel Tipper. Premi E vicino all'industria, seleziona 'Carica prodotto', quindi scegli 'Carbone' se sono disponibili più prodotti.",  "Acércate al marcador y carga carbón en el Tipper. Presiona E junto a la industria, selecciona 'Cargar producto' y luego elige 'Carbón' si hay varios productos disponibles.",  "Подойдите к маркеру и загрузите уголь в Tipper. Нажмите E рядом с предприятием, выберите 'Загрузить продукт', затем выберите 'Уголь', если доступно несколько продуктов.",  "Aproxime-se do marcador e carregue carvão no Tipper. Pressione E ao lado da indústria, selecione 'Carregar produto' e escolha 'Carvão' se houver vários produtos disponíveis.",  "İşaretçiye yaklaşın ve Tipper'a kömür yükleyin. Sanayinin yanındayken E'ye basın, 'Ürün Yükle'yi seçin, ardından birden fazla ürün mevcutsa 'Kömür'ü seçin.");
            Add(translations,  "startingGuides.step.setGpsCementFactory.title",  "Set GPS to Cement Factory",  "Définir le GPS vers la cimenterie",  "Imposta GPS su Cementificio",  "Fijar GPS hacia la fábrica de cemento",  "Поставить GPS на цементный завод",  "Definir GPS para a Fábrica de Cimento",  "GPS'i Çimento Fabrikasına Ayarla");
            Add(translations,  "startingGuides.step.setGpsCementFactory.instruction",  "Set a waypoint to the cement factory for delivery. Hint: F8 > Industries > Grand Senora Cement Factory > Add GPS Route.",  "Définissez un point de cheminement vers la cimenterie pour la livraison. Astuce : F8 > Industries > Cimenterie de Grand Senora > Ajouter un itinéraire GPS.",  "Imposta un waypoint per il cementificio per la consegna. Suggerimento: F8 > Industrie > Cementificio Grand Senora > Aggiungi percorso GPS.",  "Fija un punto en el mapa hacia la fábrica de cemento para la entrega. Consejo: F8 > Industrias > Fábrica de cemento Grand Senora > Añadir ruta GPS.",  "Установите точку маршрута до цементного завода для доставки. Подсказка: F8 > Индустрии > Цементный завод Гранд-Сенора > Добавить GPS-маршрут.",  "Defina um ponto de referência para a fábrica de cimento para a entrega. Dica: F8 > Indústrias > Fábrica de Cimento Grand Senora > Adicionar rota GPS.",  "Teslimat için çimento fabrikasına bir rota noktası ayarlayın. İpucu: F8 > Sanayiler > Grand Senora Çimento Fabrikası > GPS Rotası Ekle.");
            Add(translations,  "startingGuides.step.goCementFactory.title",  "Go to Cement Factory",  "Aller à la cimenterie",  "Vai al Cementificio",  "Ir a la fábrica de cemento",  "Ехать на цементный завод",  "Ir para a Fábrica de Cimento",  "Çimento Fabrikasına Git");
            Add(translations,  "startingGuides.step.goCementFactory.instruction",  "Drive to the cement factory marker and get ready to unload.",  "Conduisez jusqu'au marqueur de la cimenterie et préparez-vous à décharger.",  "Guida fino al marcatore del cementificio e preparati a scaricare.",  "Conduce hasta el marcador de la fábrica de cemento y prepárate para descargar.",  "Едьте к маркеру цементного завода и приготовьтесь к разгрузке.",  "Dirija até o marcador da fábrica de cimento e prepare-se para descarregar.",  "Çimento fabrikası işaretçisine sürün ve tahliye etmeye hazırlanın.");
            Add(translations,  "startingGuides.step.unloadCoal.title",  "Unload Coal",  "Décharger le charbon",  "Scarica carbone",  "Descargar carbón",  "Разгрузить уголь",  "Descarregar carvão",  "Kömürü Tahliye Et");
            Add(translations,  "startingGuides.step.unloadCoal.instruction",  "Unload the coal at the cement factory to finish the first delivery. Approach the marker, press E, open the industry interaction menu, then select 'Unload Cargo' and 'Unload Truck Cargo'.",  "Déchargez le charbon à la cimenterie pour terminer la première livraison. Approchez-vous du marqueur, appuyez sur E, ouvrez le menu d'interaction de l'industrie, puis sélectionnez 'Décharger le fret' et 'Décharger le camion'.",  "Scarica il carbone al cementificio per terminare la prima consegna. Avvicinati al marcatore, premi E, apri il menu di interazione dell'industria, quindi seleziona 'Scarica carico' e 'Scarica carico camion'.",  "Descarga el carbón en la fábrica de cemento para terminar la primera entrega. Acércate al marcador, presiona E, abre el menú de interacción de la industria, luego selecciona 'Descargar carga' y 'Descargar carga del camión'.",  "Разгрузите уголь на цементном заводы, чтобы завершить первую доставку. Подъедьте к маркеру, нажмите E, откройте меню взаимодействия с предприятием, затем выберите 'Разгрузить груз' и 'Разгрузить груз грузовика'.",  "Descarregue o carvão na fábrica de cimento para terminar a primeira entrega. Aproxime-se do marcador, pressione E, abra o menu de interação da indústria, selecione 'Descarregar carga' e 'Descarregar carga do caminhão'.",  "İlk teslimatı tamamlamak için çimento fabrikasında kömürü boşaltın. İşaretçiye yaklaşın, E'ye basın, sanayi etkileşim menüsünü açın, ardından 'Kargo Tahliye Et' ve 'Kamyon Kargosunu Tahliye Et' seçeneklerini belirleyin.");
            Add(translations,  "startingGuides.step.returnOffice.title",  "Return to office",  "Retourner au bureau",  "Torna in ufficio",  "Volver a la oficina",  "Вернуться в офис",  "Voltar para o escritório",  "Ofise dön");
            Add(translations,  "startingGuides.step.returnOffice.instruction",  "Head back to your office.",  "Dirigez-vous vers votre bureau.",  "Dirigiti verso il tuo ufficio.",  "Dirígete de vuelta a tu oficina.",  "Направляйтесь обратно в свой офис.",  "Siga de volta para o seu escritório.",  "Ofisinize doğru yola çıkın.");
            Add(translations,  "startingGuides.step.storeTruck.title",  "Store your truck",  "Stocker votre camion",  "Metti in deposito il camion",  "Guardar tu camión",  "Поставить грузовик в гараж",  "Armazenar seu caminhão",  "Kamyonunu depola");
            Add(translations,  "startingGuides.step.storeTruck.instruction",  "Store your truck in the office garage. Open the Office menu (press E when close), select 'Garage', select 'Tipper (4 Wheels)', then 'Put in Storage'.",  "Stockez votre camion dans le garage du bureau. Ouvrez le menu du bureau (appuyez sur E à proximité), sélectionnez 'Garage', sélectionnez 'Tipper (4 roues)', puis 'Mettre en stockage'.",  "Metti in deposito il tuo camion nel garage dell'ufficio. Apri il menu dell'ufficio (premi E quando sei vicino), seleziona 'Garage', seleziona 'Tipper (4 ruote)', quindi 'Metti in deposito'.",  "Guarda tu camión en el garaje de la oficina. Abre el menú de la oficina (presiona E cuando estés cerca), selecciona 'Garaje', selecciona 'Tipper (4 ruedas)' y luego 'Poner en almacenamiento'.",  "Поставьте ваш грузовик в гараж офиса. Откройте меню офиса (нажмите E, находясь рядом), выберите 'Гараж', выберите 'Tipper (4 колеса)', затем 'Поставить на хранение'.",  "Armazene seu caminhão na garagem do escritório. Abra o menu do escritório (pressione E quando estiver perto), selecione 'Garagem', selecione 'Tipper (4 Rodas)' e depois 'Colocar no Armazenamento'.",  "Kamyonunuzu ofis garajında depolayın. Ofis menüsünü açın (yakındayken E'ye basın), 'Garaj'ı seçin, 'Tipper (4 Tekerlekli)' seçeneğini belirleyin ve ardından 'Depoya Kaldır' deyin.");
            Add(translations,  "startingGuides.step.takeQuickJob.title",  "Take quick job",  "Prendre un job rapide",  "Accetta lavoro rapido",  "Tomar trabajo rápido",  "Взять быстрый заказ",  "Pegar trabalho rápido",  "Hızlı iş al");
            Add(translations,  "startingGuides.step.takeQuickJob.instruction",  "Accept a Quick Job from the dispatch board. Quick Jobs do not require a specific vehicle or permit. Open F8 > Dispatch > Quick Jobs, then accept any available job.",  "Acceptez un Job rapide depuis le tableau de répartition. Les Jobs rapides ne nécessitent ni véhicule spécifique ni permis. Ouvrez F8 > Dispatch > Jobs rapides, puis acceptez n'importe quel travail disponible.",  "Accetta un Lavoro rapido dalla bacheca di spedizione. I Lavori rapidi non richiedono un veicolo specifico o un permesso. Apri F8 > Dispatch > Lavori rapidi, quindi accetta qualsiasi lavoro disponibile.",  "Acepta un Trabajo rápido del tablero de despacho. Los Trabajos rápidos no requieren un vehículo específico ni un permiso. Abre F8 > Despacho > Trabajos rápidos y luego acepta cualquier trabajo disponible.",  "Примите Быстрый заказ с доски диспетчера. Быстрые заказы не требуют наличия специального транспорта или разрешения. Откройте F8 > Диспетчер > Быстрые заказы, затем примите любой доступный заказ.",  "Aceite um Trabalho rápido a partir do quadro de despacho. Os Trabalhos rápidos não exigem um veículo ou permissão específica. Abra F8 > Despacho > Trabalhos rápidos e aceite qualquer trabalho disponível.",  "Sevkiyat panosundan bir Hızlı iş kabul edin. Hızlı işler belirli bir araç veya izin gerektirmez. F8 > Sevkiyat > Hızlı İşler bölümünü açın, ardından uygun olan herhangi bir işi kabul edin.");
            Add(translations,  "startingGuides.step.completeQuickJob.title",  "Complete quick job",  "Terminer le job rapide",  "Completa lavoro rapido",  "Completar trabajo rápido",  "Завершить быстрый заказ",  "Concluir trabalho rápido",  "Hızlı işi tamamla");
            Add(translations,  "startingGuides.step.completeQuickJob.instruction",  "Finish the active Quick Job to learn the short-contract loop. You can review active Quick Job info in F8 > Dispatch > Accepted Contracts.",  "Terminez le Job rapide actif pour apprendre le fonctionnement des contrats courts. Vous pouvez revoir les infos du Job rapide actif dans F8 > Dispatch > Contrats acceptés.",  "Termina il Lavoro rapido attivo per imparare il ciclo dei contratti brevi. Puoi rivedere le informazioni sul Lavoro rapido attivo in F8 > Dispatch > Contratti accettati.",  "Termina el Trabajo rápido activo para aprender el ciclo de contratos cortos. Puedes revisar la información del Trabajo rápido activo en F8 > Despacho > Contratos aceptados.",  "Завершите активный Быстрый заказ, чтобы изучить цикл коротких контрактов. Вы можете просмотреть информацию об активном Быстром заказе в F8 > Диспетчер > Принятые контракты.",  "Termine o Trabalho rápido ativo para aprender o ciclo de contratos curtos. Você pode revisar as informações do Trabalho rápido ativo em F8 > Despacho > Contratos aceitos.",  "Kısa sözleşme döngüsünü öğrenmek için aktif Hızlı işi bitirin. Aktif Hızlı iş bilgilerini F8 > Sevkiyat > Kabul Edilen Sözleşmeler bölümünden inceleyebilirsiniz.");
            Add(translations,  "startingGuides.step.completeDeliveries.progressTitle",  "Complete {0} deliveries ({1}/{0})",  "Terminer {0} livraisons ({1}/{0})",  "Completa {0} consegne ({1}/{0})",  "Completar {0} entregas ({1}/{0})",  "Завершить доставок: {0} ({1}/{0})",  "Concluir {0} entregas ({1}/{0})",  "{0} teslimatı tamamla ({1}/{0})");
            Add(translations,  "startingGuides.step.completeDeliveries.instruction",  "Keep running routes until you reach five completed deliveries.",  "Continuez à effectuer des trajets jusqu'à ce que vous atteigniez cinq livraisons terminées.",  "Continua a eseguire rotte finché non raggiungi cinque consegne completate.",  "Sigue realizando rutas hasta que alcances las cinco entregas completadas.",  "Продолжайте выполнять маршруты, пока не наберете пять завершенных доставок.",  "Continue executando rotas até atingir cinco entregas concluídas.",  "Beş tamamlanmış teslimata ulaşana kadar rotaları yapmaya devam edin.");
            Add(translations,  "startingGuides.step.buyFirstPermit.title",  "Buy first permit",  "Acheter un premier permis",  "Acquista primo permesso",  "Comprar primer permiso",  "Купить первое разрешение",  "Comprar primeira permissão",  "İlk izni satın al");
            Add(translations,  "startingGuides.step.buyFirstPermit.instruction",  "Permits give you access to sites for loading and unloading resources. Purchase your first contractor permit to unlock another lane.",  "Les permis vous donnent accès aux sites pour charger et décharger des ressources. Achetez votre premier permis d'entrepreneur pour débloquer une autre voie.",  "I permessi ti danno accesso ai siti per caricare e scaricare risorse. Acquista il tuo primo permesso da appaltatore per sbloccare un'altra corsia.",  "Los permisos te dan acceso a los sitios para cargar y descargar recursos. Compra tu primer permiso de contratista para desbloquear otra ruta.",  "Разрешения дают вам доступ к объектам для погрузки и выгрузки ресурсов. Купите свое первое разрешение подрядчика, чтобы разблокировать новую линию.",  "As permissões dão acesso aos locais para carregar e descarregar recursos. Compre sua primeira permissão de empreiteiro para desbloquear outra rota.",  "İzinler, kaynakları yüklemek ve boşaltmak için tesislere erişim sağlar. Başka bir hattın kilidini açmak için ilk yüklenici izninizi satın alın.");
            Add(translations,  "startingGuides.step.visitBank.title",  "Visit a bank",  "Visiter une banque",  "Visita una banca",  "Visitar un banco",  "Посетить банк",  "Visitar um banco",  "Bir bankayı ziyaret et");
            Add(translations,  "startingGuides.step.visitBank.instruction",  "Visit a bank branch to review company financing options. Bank loans can help you grow faster, but watch interest rates and payment deadlines.",  "Visitez une succursale bancaire pour examiner les options de financement de l'entreprise. Les prêts bancaires peuvent vous aider à vous développer plus rapidement, mais surveillez les taux d'intérêt et les échéances de paiement.",  "Visita una filiale bancaria per esaminare le opzioni di finanziamento aziendale. I prestiti bancari possono aiutarti a crescere più velocemente, ma fai attenzione ai tassi di interesse e alle scadenze dei pagamenti.",  "Visita una sucursal bancaria para revisar las opciones de financiación de la empresa. Los préstamos bancarios pueden ayudarte a crecer más rápido, pero ten cuidado con las tasas de interés y los plazos de pago.",  "Посетите отделение банка, чтобы ознакомиться с вариантами финансирования компании. Банковские кредиты могут помочь вам расти быстрее, но следите за процентными ставками и сроками платежей.",  "Visite uma agência bancária para analisar as opções de financiamento da empresa. Os empréstimos bancários podem ajudá-lo a crescer mais rápido, mas fique atento às taxas de juros e aos prazos de pagamento.",  "Şirket finansman seçeneklerini incelemek için bir banka şubesini ziyaret edin. Banka kredileri daha hızlı büyümenize yardımcı olabilir, ancak faiz oranlarına ve ödeme tarihlerine dikkat edin.");
            Add(translations,  "startingGuides.step.purchaseFreeMixer.title",  "Purchase free Mixer",  "Acheter le Mixer gratuit",  "Acquista Mixer gratuito",  "Comprar Mixer gratis",  "Купить бесплатный Mixer",  "Comprar Mixer gratuito",  "Ücretsiz Mixer'ı satın al");
            Add(translations,  "startingGuides.step.purchaseFreeMixer.instruction",  "Return to the commercial dealership and claim the free Mixer.",  "Retournez chez le concessionnaire commercial et réclamez le Mixer gratuit.",  "Torna alla concessionaria commerciale e riscatta il Mixer gratuito.",  "Regresa al concesionario comercial y reclama el Mixer gratuito.",  "Вернитесь в коммерческий автосалон и заберите бесплатный Mixer.",  "Volte à concessionária comercial e resgate o Mixer gratuito.",  "Ticari araç galerisine geri dönün ve ücretsiz Mixer'ı alın.");
            Add(translations,  "startingGuides.step.completeMixerDelivery.title",  "Complete Mixer delivery",  "Terminer la livraison au Mixer",  "Completa consegna con Mixer",  "Completar entrega de Mixer",  "Завершить доставку на Mixer",  "Concluir entrega do Mixer",  "Mixer teslimatını tamamla");
            Add(translations,  "startingGuides.step.completeMixerDelivery.instruction",  "Run one full Mixer delivery to finish the starting guide. Load cement from the cement factory and deliver it to any construction site. Hint: use F8 to find which construction site accepts cement and set a GPS route.",  "Effectuez une livraison complète au Mixer pour terminer le guide de démarrage. Chargez du ciment de la cimenterie et livrez-le sur n'importe quel chantier de construction. Astuce : utilisez F8 pour trouver quel chantier accepte le ciment et définissez un itinéraire GPS.",  "Esegui una consegna completa con il Mixer per terminare la guida introduttiva. Carica il cemento dal cementificio e consegnalo a un cantiere edile qualsiasi. Suggerimento: usa F8 per scoprire quale cantiere edile accetta cemento e imposta un percorso GPS.",  "Realiza una entrega completa de Mixer para finalizar la guía de inicio. Carga cemento de la fábrica de cemento y entrégalo en cualquier obra de construcción. Consejo: usa F8 para buscar qué obra acepta cemento y fija una ruta GPS.",  "Выполните одну полную доставку на Mixer, чтобы завершить стартовое руководство. Загрузите цемент на цементном заводе и доставьте его на любую строительную площадку. Подсказка: используйте F8, чтобы узнать, какая стройка принимает цемент, и проложите GPS-маршрут.",  "Faça uma entrega completa com o Mixer para terminar o guia de início. Carregue cimento da fábrica de cimento e entregue-o em qualquer canteiro de obras. Dica: use F8 para descobrir qual canteiro de obras aceita cimento e defina uma rota GPS.",  "Başlangıç rehberini bitirmek için bir tam Mixer teslimatı gerçekleştirin. Çimento fabrikasından çimento yükleyin ve bunu herhangi bir şantiyeye teslim edin. İpucu: Hangi şantiyenin çimento kabul ettiğini bulmak ve bir GPS rotası ayarlamak için F8'i kullanın.");

            Add(translations,  ModTextKey.DetailSpeedUnit,  "Switch the cruise-control speed display between imperial and metric units.",  "Bascule l'affichage du régulateur entre impérial et métrique.",  "Cambia l'visualizzazione del cruise control tra imperiale e metrico.",  "Cambia el indicador del control de crucero entre imperial y métrico.",  "Переключает показ круиз-контроля между имперскими и метрическими единицами.",  "Troca a exibição do controle de cruzeiro entre imperial e métrico.",  "Hız sabitleyici göstergesini imperial ve metrik arasında değiştirir.");
            Add(translations,  ModTextKey.DetailVehicleFuel,  "Enable vehicle fuel usage for cargo operations.",  "Active l'usage du carburant pour les opérations cargo.",  "Abilita il carburante per le operazioni cargo.",  "Activa el combustible para operaciones de carga.",  "Включает расход топлива для грузовых операций.",  "Ativa o uso de combustível nas operações de carga.",  "Yük operasyonları için araç yakıtını etkinleştirir.");
            Add(translations,  ModTextKey.DetailCargoWeightPower,  "Reduce engine power as carried cargo weight increases.",  "Réduit la puissance moteur à mesure que le poids de la cargaison transportée augmente.",  "Riduce la potenza del motore all'aumentare del peso del carico trasportato.",  "Reduce la potencia del motor a medida que aumenta el peso de la carga transportada.",  "Снижает мощность двигателя по мере увеличения веса перевозимого груза.",  "Reduz a potência do motor à medida que o peso da carga transportada aumenta.",  "Taşınan yükün ağırlığı arttıkça motor gücünü düşürür.");
            Add(translations,  ModTextKey.DetailCruiseControl,  "Hold the current speed until you brake, disable it, or leave the vehicle.",  "Maintient la vitesse actuelle jusqu'à ce que vous freiniez, le désactiviez ou quittiez le véhicule.",  "Mantiene la velocità corrente finché non freni, lo disabiliti o lasci il veicolo.",  "Mantiene la velocidad actual hasta que frenes, lo desactives o salgas del vehículo.",  "Удерживает текущую скорость, пока вы не нажмете тормоз, не отключите её или не выйдете из транспорта.",  "Mantém a velocidade atual até você frear, desativá-lo ou sair do veículo.",  "Siz frene basana, kapatana veya araçtan çıkana kadar mevcut hızı korur.");
            Add(translations,  ModTextKey.DetailCargoDamage,  "Enable cargo loss and condition damage from collisions.",  "Active la perte de cargaison et les dégâts dus aux collisions.",  "Abilita perdita carico e danni da collisione.",  "Activa pérdida de carga y daños por colisiones.",  "Включает потерю груза и урон от столкновений.",  "Ativa perda de carga e dano por colisões.",  "Çarpışmalardan yük kaybı ve hasarını etkinleştirir.");
            Add(translations,  ModTextKey.DetailIndustryPriceMechanic,  "Require industry purchases and owner-cut payouts until bought.",  "Exige l'achat des industries et les commissions du propriétaire avant acquisition.",  "Richiede acquisti industria e percentuale proprietario fino all'acquisto.",  "Requiere comprar industrias y pagar comisión del dueño hasta adquirirlas.",  "Требует покупку отрасли и выплаты владельцу до выкупа.",  "Exige compra da indústria e repasse ao dono até a aquisição.",  "Satın alana kadar endüstri satın alma ve sahip payı ödemesi gerektirir.");
            Add(translations,  ModTextKey.DetailLicensingSystem,  "Require contractor permits before transporting cargo to or from industries.",  "Exige des permis avant de transporter du cargo vers ou depuis les industries.",  "Richiede permessi prima di trasportare carichi da o verso le industrie.",  "Requiere permisos antes de transportar carga hacia o desde industrias.",  "Требует разрешения перед перевозкой груза к отраслям и от них.",  "Exige licenças antes de transportar carga para ou das indústrias.",  "Endüstrilere yük taşımadan önce izin gerektirir.");
            Add(translations,  ModTextKey.DetailCorridorRestriction,  "Require unlocked corridors before cross-district logistics routes can operate.",  "Exige des corridors débloqués avant que les routes logistiques inter-districts puissent fonctionner.",  "Richiede corridoi sbloccati prima che le rotte logistiche tra distretti possano operare.",  "Requiere corredores desbloqueados antes de que puedan operar rutas logísticas entre distritos.",  "Требует разблокированные коридоры, прежде чем межрайонные логистические маршруты смогут работать.",  "Exige corredores desbloqueados antes que rotas logísticas entre distritos possam operar.",  "İlçeler arası lojistik rotaların çalışması için koridorların önce açılmış olmasını gerektirir.");
            Add(translations,  ModTextKey.DetailReputationSystem,  "Disable district reputation completely. Reputation gates, bonuses, penalties, and notices become inactive while off.",  "Désactive totalement la réputation des districts. Les blocages, bonus, pénalités et notifications deviennent inactifs.",  "Disattiva completamente la reputazione dei distretti. Blocchi, bonus, penalità e notifiche diventano inattivi.",  "Desactiva por completo la reputación de distrito. Bloqueos, bonificaciones, penalizaciones y avisos quedan inactivos.",  "Полностью отключает репутацию районов. Ограничения, бонусы, штрафы и уведомления становятся неактивны.",  "Desativa totalmente a reputação distrital. Restrições, bônus, penalidades e avisos ficam inativos.",  "Bölge itibarını tamamen kapatır. Kısıtlar, bonuslar, cezalar ve bildirimler devre dışı kalır.");
            Add(translations,  ModTextKey.DetailOfficeGarageLimit,  "Disable office garage capacity checks for purchases, storage, retrieval, spawning, and assignments.",  "Désactive les limites du garage pour achat, stockage, sortie, spawn et affectation.",  "Disattiva i controlli capienza garage per acquisti, deposito, ritiro, spawn e assegnazioni.",  "Desactiva los límites del garaje para compra, guardado, retirada, aparición y asignación.",  "Отключает лимит гаража офиса для покупки, хранения, выдачи, спавна и назначений.",  "Desativa os limites da garagem do escritório para compra, armazenamento, retirada, spawn e atribuição.",  "Satın alma, depolama, çağırma, doğma ve atamalar için ofis garaj kapasite kontrollerini kapatır.");
            Add(translations,  ModTextKey.DetailOfficeNpcLimitEnabled,  "Require Construction Site Cabin capacity before hiring additional NPCs.",  "Exige une capacité de cabane de chantier de construction suffisante avant d'embaucher des PNJ supplémentaires.",  "Richiede capacità della baracca del cantiere edile prima di assumere altri NPC.",  "Requiere capacidad de caseta de obra antes de contratar NPCs adicionales.",  "Требует наличие свободных мест в бытовке строительной площадки перед наймом новых NPC.",  "Exige capacidade de cabine de canteiro de obras antes de contratar NPCs adicionais.",  "Ek NPC kiralamadan önce Şantiye Kulübesi kapasitesi gerektirir.");
            Add(translations,  ModTextKey.DetailOfficeNpcLimitDisabled,  "Ignore Construction Site Cabin capacity when hiring NPCs.",  "Ignore la capacité de cabane de chantier de construction lors de l'embauche des PNJ.",  "Ignora la capacità della baracca del cantiere edile quando si assumono NPC.",  "Ignora la capacidad de caseta de obra al contratar NPCs.",  "Игнорирует вместимость бытовки строительной площадки при найме NPC.",  "Ignora a capacidade de cabine de canteiro de obras ao contratar NPCs.",  "NPC kiralarken Şantiye Kulübesi kapasitesini göz ardı eder.");
            Add(translations,  ModTextKey.DetailNpcRouteLimit,  "Set the maximum route slots per hired NPC. 0 disables Hiring NPC entirely.",  "Définit le nombre maximum de routes par PNJ recruté. 0 désactive le recrutement PNJ.",  "Imposta il numero massimo di rotte per ogni NPC assunto. 0 disattiva il reclutamento NPC.",  "Define el máximo de rutas por NPC contratado. 0 desactiva por completo los NPC contratados.",  "Зает максимум маршрутов на одного нанятого NPC. 0 полностью отключает найм NPC.",  "Define o máximo de rotas por NPC contratado. 0 desativa totalmente o Hiring NPC.",  "Kiralanan NPC başına en fazla rota sayısını ayarlar. 0, NPC işe alımını tamamen kapatır.");
            Add(translations,  ModTextKey.DetailMaxModuleLimitPerSite,  "Set the maximum total module upgrades allowed per industry site (1-10). Placements that would exceed this cap are blocked.",  "Définit la limite maximale de modules d'amélioration par site industriel (1-10). Les placements dépassant ce cap sont bloqués.",  "Imposta il limite massimo di potenziamenti modulo per sito industriale (1-10). Posizionamenti oltre questa soglia sono bloccati.",  "Define el límite máximo de mejoras de módulo por sitio industrial (1-10). Las colocaciones que superen este límite se bloquean.",  "Задаёт максимальное число улучшений модулей на промзону (1-10). Размещения, превышающие этот лимит, блокируются.",  "Define o limite máximo de melhorias de módulo por local industrial (1-10). Instalações que excedam esse limite são bloqueadas.",  "Sanayi tesisi başına izin verilen en fazla toplam modül yükseltmesini ayarlar (1-10). Bu sınırı aşacak yerleştirmeler engellenir.");
            Add(translations,  ModTextKey.DetailCreateSave,  "Starts a fresh game as {0}.state.xml",  "Démarre une nouvelle partie sous {0}.state.xml",  "Avvia una nuova partita come {0}.state.xml",  "Inicia una nueva partida como {0}.state.xml",  "Запускает новую игру как {0}.state.xml",  "Inicia um novo jogo como {0}.state.xml",  "Yeni oyunu {0}.state.xml olarak başlatır");
            Add(translations,  ModTextKey.DetailLanguage,  "Apply language changes immediately across localized menu and status text.",  "Applique immédiatement la langue aux menus et statuts localisés.",  "Applica subito la lingua a menu e stati localizzati.",  "Aplica de inmediato el idioma a menús y estados localizados.",  "Сразу применяет язык к локализованным меню и статусам.",  "Aplica imediatamente o idioma a menus e textos de status localizados.",  "Yerelleştirilmiş menü ve durum yazılarına dili hemen uygular.");
            Add(translations,  ModTextKey.DetailLanguageEnglishFallback,  "English is active. Left or right switches to a translated language.",  "Le secours anglais est actif. Gauche ou droite passe à une langue traduite.",  "Il fallback inglese è attivo. Sinistra o destra passa a una lingua tradotta.",  "El inglés de respaldo está activo. Izquierda o derecha cambia a un idioma traducido.",  "Активен английский запасной язык. Влево или вправо переключает на перевод.",  "O fallback em inglês está ativo. Esquerda ou direita troca para um idioma traduzido.",  "İngilizce yedek dil etkin. Sağ veya sol ile çevrilmiş dillere geçin.");
            Add(translations,  ModTextKey.DetailSpeedUnitChanged,  "Speed units set to {0}.",  "Unités de vitesse réglées sur {0}.",  "Unità velocità impostate su {0}.",  "Unidades de velocidad establecidas en {0}.",  "Единицы скорости установлены: {0}.",  "Unidades de velocidade definidas para {0}.",  "Hız birimleri {0} olarak ayarlandı.");
            Add(translations,  ModTextKey.DetailColorblindMode,  "Apply a high-contrast mod UI palette tuned for the selected color vision mode.",  "Applique une palette à fort contraste adaptée au mode de vision sélectionné.",  "Applica una palette ad alto contrasto per la modalità visiva selezionata.",  "Aplica una paleta de alto contraste según la visión seleccionada.",  "Применяет высококонтрастную палитру интерфейса под выбранный режим зрения.",  "Aplica uma paleta de alto contraste ajustada ao modo de visão selecionado.",  "Seçilen renk görme moduna göre yüksek kontrastlı arayüz paleti uygular.");
            Add(translations,  ModTextKey.DetailOptions,  "Adjust language, speed units, and accessibility options.",  "Ajustez la langue et les options d'accessibilité.",  "Regola lingua e accessibilità.",  "Ajusta idioma y accesibilidad.",  "Настройте язык и доступность.",  "Ajuste idioma e acessibilidade.",  "Dil ve erişilebilirlik seçeneklerini ayarlayın.");
            Add(translations,  ModTextKey.DetailOptionsNavigate,  "Left or right cycles the available options.",  "Gauche ou droite fait défiler les options.",  "Sinistra o destra scorrono le opzioni.",  "Izquierda o derecha recorren las opciones.",  "Влево или вправо переключают варианты.",  "Esquerda ou direita percorrem as opções.",  "Sağ veya sol mevcut seçenekleri değiştirir.");
            Add(translations,  ModTextKey.DetailDifficultySettingsLockedStatus,  "Difficulty settings are sealed for this save. Create a new save to change them.",  "Les paramètres de difficulté sont scellés pour cette sauvegarde. Créez une nouvelle sauvegarde pour les modifier.",  "Le impostazioni difficoltà sono bloccate per questo salvataggio. Crea un nuovo salvataggio per cambiarle.",  "Los ajustes de dificultad están sellados para esta partida. Crea una nueva partida para cambiarlos.",  "Настройки сложности зафиксированы для этого сохранения. Создайте новое сохранение, чтобы изменить их.",  "As configurações de dificuldade estão seladas para este save. Crie um novo save para alterá-las.",  "Bu kayıt için zorluk ayarları mühürlü. Değiştirmek için yeni kayıt oluşturun.");
            Add(translations,  ModTextKey.DetailDifficultyTemplatesActions,  "Save the current full difficulty profile or load a saved one.",  "Sauvegardez le profil de difficulté actuel ou chargez-en un existant.",  "Salva il profilo difficoltà completo corrente o caricane uno salvato.",  "Guarda el perfil de dificultad completo actual o carga uno guardado.",  "Сохраните текущий профиль сложности или загрузите сохраненный.",  "Salve o perfil de dificuldade completo atual ou carregue um salvo.",  "Mevcut tam zorluk profilini kaydedin veya kaydedilmiş bir profili yükleyin.");
            Add(translations,  ModTextKey.DetailDifficultyTemplatesActionsLocked,  "Save the current full difficulty profile here. Loading a saved template is unavailable while the active save is locked.",  "Sauvegardez le profil complet ici. Le chargement d'un modèle est indisponible lorsque la sauvegarde active est verrouillée.",  "Salva il profilo difficoltà completo qui. Il caricamento di un modello non è disponibile con salvataggio bloccato.",  "Guarda el perfil de dificultad completo aquí. Cargar una plantilla no está disponible si la partida está bloqueada.",  "Сохраните текущий профиль сложности здесь. Загрузка шаблона недоступна, пока активное сохранение заблокировано.",  "Salve o perfil de dificuldade completo aqui. Carregar um modelo salvo não está disponível enquanto o save ativo estiver bloqueado.",  "Mevcut tam zorluk profilini buraya kaydedin. Etkin kayıt kilitliyken kaydedilmiş bir şablonu yüklemek mümkün değildir.");
            Add(translations,  ModTextKey.DetailDifficultyEnableAll,  "Turn every boolean difficulty rule on or enforced. Economy preset, wages, and NPC route limit stay as-is.",  "Active ou force toutes les règles de difficulté booléennes. Le préréglage de l'économie, les salaires et la limite de routes PNJ restent inchangés.",  "Attiva o forza ogni regola di difficoltà booleana. Preset economico, salari e limite rotte NPC rimangono invariati.",  "Activa o fuerza todas las reglas de dificultad booleanas. El ajuste económico, los sueldos y el límite de rutas NPC no cambian.",  "Включает или принудительно активирует все логические правила сложности. Настройки экономики, зарплаты и лимит маршрутов NPC остаются прежними.",  "Ativa ou força todas as regras de dificuldade booleanas. Predefinição econômica, salários e limite de rotas NPC permanecem inalterados.",  "Tüm mantıksal zorluk kurallarını açar veya zorunlu kılar. Ekonomi ön ayarı, maaşlar ve NPC rota sınırı olduğu gibi kalır.");
            Add(translations,  ModTextKey.DetailDifficultyDisableAll,  "Turn every boolean difficulty rule off or bypassed. Economy preset, wages, and NPC route limit stay as-is.",  "Désactive ou contourne toutes les règles de difficulté booléennes. Le préréglage de l'économie, les salaires et la limite de routes PNJ restent inchangés.",  "Disattiva o ignora ogni regola di difficoltà booleana. Preset economico, salari e limite rotte NPC rimangono invariati.",  "Desactiva o ignora todas las reglas de dificultad booleanas. El ajuste económico, los sueldos y el límite de rutas NPC no cambian.",  "Отключает или обходит все логические правила сложности. Настройки экономики, зарплаты и лимит маршрутов NPC остаются прежними.",  "Desativa ou ignora todas as regras de dificuldade booleanas. Predefinição econômica, salários e limite de rotas NPC permanecem inalterados.",  "Tüm mantıksal zorluk kurallarını kapatır veya bypass eder. Ekonomi ön ayarı, maaşlar ve NPC rota sınırı olduğu gibi kalır.");
            Add(translations,  ModTextKey.DetailDifficultyBulkActionBlockedLocked,  "Locked by the active save. Bulk actions are unavailable here.",  "Verrouillé par la sauvegarde active. Les actions de masse sont indisponibles ici.",  "Bloccato dal salvataggio attivo. Le azioni di massa non sono disponibili qui.",  "Bloqueado por la partida activa. Las acciones masivas no están disponibles aquí.",  "Заблокировано активным сохранением. Групповые действия здесь недоступны.",  "Bloqueado pelo save ativo. Ações em massa não estão disponíveis aqui.",  "Etkin kayıt tarafından kilitlendi. Toplu işlemler burada kullanılamaz.");
            Add(translations,  ModTextKey.DetailDifficultySaveTemplate,  "Save the current full difficulty profile as a reusable global template.",  "Sauvegardez le profil de difficulté actuel sous forme de modèle global réutilisable.",  "Salva il profilo difficoltà completo corrente come modello globale riutilizzabile.",  "Guarda el perfil de dificultad completo actual como una plantilla global reutilizable.",  "Сохраните текущий профиль сложности как глобальный многоразовый шаблон.",  "Salve o perfil de dificuldade completo atual como um modelo global reutilizável.",  "Mevcut tam zorluk profilini yeniden kullanılabilir genel bir şablon olarak kaydedin.");
            Add(translations,  ModTextKey.DetailDifficultyLoadTemplate,  "Load a saved full difficulty profile into the current settings surface.",  "Chargez un profil de difficulté complet sauvegardé dans l'interface de paramètres actuelle.",  "Carica un profilo difficoltà completo salvato nella schermata delle impostazioni corrente.",  "Carga un perfil de dificultad completo guardado en la ventana de ajustes actuales.",  "Загрузите сохраненный профиль сложности в текущее меню настроек.",  "Carregue um perfil de dificuldade completo salvo na tela de configurações atual.",  "Kaydedilmiş bir tam zorluk profilini mevcut ayarlar ekranına yükleyin.");
            Add(translations,  ModTextKey.DetailDifficultyNoTemplatesFound,  "Save a template first to load it here.",  "Sauvegardez d'abord un modèle pour pouvoir le charger ici.",  "Salva prima un modello per poterlo caricare qui.",  "Primero guarda una plantilla para cargarla aquí.",  "Сначала сохраните шаблон, чтобы загрузить его здесь.",  "Salve um modelo primeiro para carregá-lo aqui.",  "Buraya yüklemek için önce bir şablon kaydedin.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateSaved,  "Saved difficulty template '{0}'.",  "Modèle de difficulté '{0}' sauvegardé.",  "Modello difficoltà '{0}' salvato.",  "Plantilla de dificultad '{0}' guardada.",  "Шаблон сложности '{0}' сохранен.",  "Modelo de dificuldade '{0}' salvo.",  "Zorluk şablonu '{0}' kaydedildi.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateOverwritten,  "Overwrote difficulty template '{0}'.",  "Modèle de difficulté '{0}' écrasé.",  "Modello difficoltà '{0}' sovrascritto.",  "Plantilla de dificultad '{0}' sobrescrita.",  "Шаблон сложности '{0}' перезаписан.",  "Modelo de dificuldade '{0}' sobrescrito.",  "Zorluk şablonunun '{0}' üzerine yazıldı.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateLoaded,  "Loaded difficulty template '{0}'.",  "Modèle de difficulté '{0}' chargé.",  "Modello difficoltà '{0}' caricato.",  "Plantilla de dificultad '{0}' cargada.",  "Шаблон сложности '{0}' загружен.",  "Modelo de dificuldade '{0}' carregado.",  "Zorluk şablonu '{0}' yüklendi.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateSaveCancelled,  "Difficulty template save cancelled.",  "Sauvegarde du modèle de difficulté annulée.",  "Salvataggio modello difficoltà annullato.",  "Guardado de plantilla de dificultad cancelado.",  "Сохранение шаблона сложности отменено.",  "Salvamento do modelo de dificuldade cancelado.",  "Zorluk şablonu kaydetme işlemi iptal edildi.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateNameInvalid,  "Enter a valid difficulty template name.",  "Entrez un nom de modèle de difficulté valide.",  "Inserisci un nome modello difficoltà valido.",  "Introduce un nombre de plantilla de dificultad válido.",  "Введите корректное имя для шаблона сложности.",  "Digite um nome de modelo de dificuldade válido.",  "Geçerli bir zorluk şablonu adı girin.");
            Add(translations,  ModTextKey.DetailDifficultyTemplateBlockedLocked,  "Locked by the active save. Loading a difficulty template is unavailable here.",  "Verrouillé par la sauvegarde active. Le chargement d'un modèle de difficulté est indisponible ici.",  "Bloccato dal salvataggio attivo. Il caricamento di un modello difficoltà non è disponibile qui.",  "Bloqueado por la partida activa. Cargar una plantilla de dificultad no está disponible aquí.",  "Заблокировано активным сохранением. Загрузка шаблона сложности здесь недоступна.",  "Bloqueado pelo save ativo. Carregar um modelo de dificuldade não está disponível aqui.",  "Etkin kayıt tarafından kilitlendi. Zorluk şablonu yükleme işlemi burada kullanılamaz.");
            Add(translations,  ModTextKey.DetailPersistenceEnabled,  "Industry persistence enabled.",  "Persistance des industries activée.",  "Persistenza industrie attivata.",  "Persistencia industrial activada.",  "Сохранение отраслей включено.",  "Persistência da indústria ativada.",  "Endüstri kalıcılığı etkinleştirildi.");
            Add(translations,  ModTextKey.DetailPersistenceDisabled,  "Industry persistence disabled.",  "Persistance des industries désactivée.",  "Persistenza industrie disattivata.",  "Persistencia industrial desactivada.",  "Сохранение отраслей выключено.",  "Persistência da indústria desativada.",  "Endüstri kalıcılığı devre dışı.");
            Add(translations,  ModTextKey.DetailDebugUnavailable,  "Debug tools are only available while a debugger is attached.",  "Les outils debug ne sont disponibles qu'avec un débogueur attaché.",  "Gli strumenti debug sono disponibili solo con un debugger collegato.",  "Las herramientas de depuración solo están disponibles con un depurador conectado.",  "Инструменты отладки доступны только при подключенном отладчике.",  "Ferramentas de depuração só ficam disponíveis com um depurador anexado.",  "Hata ayıklama araçları yalnızca bir debugger bağlıyken kullanılabilir.");
            Add(translations,  ModTextKey.DetailLoadSavedState,  "Loaded saved industry state for {0} nodes.",  "État industriel chargé pour {0} nœuds.",  "Stato industria caricato per {0} nodi.",  "Estado industrial cargado para {0} nodos.",  "Загружено состояние отрасли для {0} узлов.",  "Estado da indústria carregado para {0} nós.",  "{0} düğüm için kayıtlı endüstri durumu yüklendi.");
            Add(translations,  ModTextKey.DetailLoadSavedSettings,  "Loaded saved game settings.",  "Paramètres de jeu chargés.",  "Impostazioni di gioco caricate.",  "Se cargaron los ajustes guardados.",  "Настройки игры загружены.",  "Configurações salvas carregadas.",  "Kayıtlı oyun ayarları yüklendi.");
            Add(translations,  ModTextKey.DetailNoSavedState,  "No saved industry state found yet.",  "Aucun état industriel sauvegardé pour le moment.",  "Nessuno stato industria salvato trovato.",  "Aún no se encontró estado industrial guardado.",  "Сохраняемое состояние отрасли пока не найдено.",  "Nenhum estado da indústria salvo encontrado ainda.",  "Henüz kayıtlı endüstri durumu bulunamadı.");
            Add(translations,  ModTextKey.DetailNoSavePath,  "No save path is available.",  "Aucun chemin de sauvegarde disponible.",  "Nessun percorso di salvataggio disponibile.",  "No hay ruta de guardado disponible.",  "Путь сохранения недоступен.",  "Nenhum caminho de save disponível.",  "Kullanılabilir kayıt yolu yok.");
            Add(translations,  ModTextKey.DetailSaveCreationCancelled,  "Save creation cancelled.",  "Création de sauvegarde annulée.",  "Creazione salvataggio annullata.",  "Creación de partida cancelada.",  "Создание сохранения отменено.",  "Criação de save cancelada.",  "Kayıt oluşturma iptal edildi.");
            Add(translations,  ModTextKey.DetailSaveNameInvalid,  "Enter a valid save name.",  "Entrez un nom de sauvegarde valide.",  "Inserisci un nome salvataggio valido.",  "Introduce un nombre de partida válido.",  "Введите корректное имя сохранения.",  "Digite um nome de save válido.",  "Geçerli bir kayıt adı girin.");
            Add(translations,  ModTextKey.DetailSaveExists,  "A save with that name already exists.",  "Une sauvegarde avec ce nom existe déjà.",  "Esiste già un salvataggio con questo nome.",  "Ya existe una partida con ese nombre.",  "Сохранение с таким именем уже существует.",  "Já existe um save com esse nome.",  "Bu adda bir kayıt zaten var.");
            Add(translations,  ModTextKey.DetailNoPendingSaveName,  "No save name selected.",  "Aucun nom de sauvegarde sélectionné.",  "Nessun nome salvataggio selezionato.",  "No hay nombre de partida seleccionado.",  "Имя сохранения не выбрано.",  "Nenhum nome de save selecionado.",  "Seçili bir kayıt adı yok.");
            Add(translations,  ModTextKey.DetailSelectedSaveMissing,  "Selected save was not found.",  "La sauvegarde sélectionnée est introuvable.",  "Il salvataggio selezionato non è stato trovato.",  "No se encontró la partida seleccionada.",  "Выбранное сохранение не найдено.",  "O save selecionado não foi encontrado.",  "Seçilen kayıt bulunamadı.");
            Add(translations,  ModTextKey.DetailCreateOrLoadNamedSave,  "Create or load a named save first.",  "Créez ou chargez d'abord une sauvegarde nommée.",  "Crea o carica prima un salvataggio con nome.",  "Crea o carga primero una partida con nombre.",  "Сначала создайте или загрузите именованное сохранение.",  "Crie ou carregue um save nomeado primeiro.",  "Önce adlandırılmış bir kayıt oluşturun veya yükleyin.");
            Add(translations,  ModTextKey.DetailSaveCreated,  "Created save '{0}'.",  "Sauvegarde '{0}' créée.",  "Salvataggio '{0}' creato.",  "Partida '{0}' creada.",  "Сохранение '{0}' создано.",  "Save '{0}' criado.",  "'{0}' kaydı oluşturuldu.");
            Add(translations,  ModTextKey.DetailSaveLoaded,  "Loaded save '{0}'.",  "Sauvegarde '{0}' chargée.",  "Salvataggio '{0}' caricato.",  "Partida '{0}' cargada.",  "Сохранение '{0}' загружено.",  "Save '{0}' carregado.",  "'{0}' kaydı yüklendi.");
            Add(translations,  ModTextKey.DetailSaveDeleted,  "Deleted save '{0}'.",  "Sauvegarde '{0}' supprimée.",  "Salvataggio '{0}' eliminato.",  "Partida '{0}' eliminada.",  "Сохранение '{0}' удалено.",  "Save '{0}' excluído.",  "'{0}' kaydı silindi.");
            Add(translations,  ModTextKey.DetailSaveSaved,  "Saved '{0}'.",  "'{0}' sauvegardé.",  "'{0}' salvato.",  "'{0}' guardado.",  "'{0}' сохранено.",  "'{0}' salvo.",  "'{0}' kaydedildi.");
            Add(translations,  ModTextKey.DetailLoadedSuccessfully,  "Loaded successfully.",  "Chargé avec succès.",  "Caricato con successo.",  "Cargado correctamente.",  "Успешно загружено.",  "Carregado com sucesso.",  "Başarıyla yüklendi.");
            Add(translations,  ModTextKey.DetailMechanicsEnabled,  "Mod mechanics enabled.",  "Mécaniques du mod activées.",  "Meccaniche mod attivate.",  "Mecánicas del mod activadas.",  "Механики мода включены.",  "Mecânicas do mod ativadas.",  "Mod mekanikleri etkinleştirildi.");
            Add(translations,  ModTextKey.DetailMechanicsDisabled,  "Mod mechanics disabled.",  "Mécaniques du mod désactivées.",  "Meccaniche mod disattivate.",  "Mecánicas del mod desactivadas.",  "Механики мода отключены.",  "Mecânicas do mod desativadas.",  "Mod mekanikleri devre dışı.");
